<template><div><DsPageHeader title="Grupos de variáveis" subtitle="Cadastro e associação de variáveis" icon="diagram-3"/><DsPageShell><div class="flex justify-between mb-4"><DsButton variant="secondary" @click="association=true">Associar variáveis</DsButton><DsButton v-if="auth.isAdmin" variant="success" @click="open()">Novo grupo</DsButton></div><DsAlert v-if="error" variant="error">{{error}}</DsAlert><DsTable v-else><template #head><tr><th>Código</th><th>Nome</th><th>Descrição</th><th>Status</th><th>Variáveis</th><th/></tr></template><tr v-for="g in grupos" :key="g.codGrupo"><td>{{g.codGrupo}}</td><td>{{g.nome}}</td><td>{{g.descricao||'-'}}</td><td>{{g.ativo?'Ativo':'Inativo'}}</td><td>{{g.quantidadeVariaveis}}</td><td><div v-if="auth.isAdmin" class="flex justify-end gap-2"><DsButton size="sm" variant="secondary" @click="open(g)">Editar</DsButton><DsButton size="sm" variant="danger" @click="remove(g)">Excluir</DsButton></div></td></tr></DsTable></DsPageShell><DsModal v-model="modal" :title="editing?'Editar grupo':'Novo grupo'"><div class="space-y-3"><DsInput v-model="form.nome" label="Nome"/><DsTextarea v-model="form.descricao" label="Descrição"/><DsSelect v-model="form.ativo" label="Status"><option value="1">Ativo</option><option value="0">Inativo</option></DsSelect></div><template #footer><DsButton variant="secondary" @click="modal=false">Cancelar</DsButton><DsButton @click="save">Salvar</DsButton></template></DsModal><DsModal v-model="association" title="Associar variáveis" size="xl"><div class="space-y-3"><DsSelect v-model="targetGroup" label="Grupo de destino"><option value="">Sem grupo</option><option v-for="g in grupos" :key="g.codGrupo" :value="String(g.codGrupo)">{{g.nome}}</option></DsSelect><DsSearchInput v-model="search" placeholder="Filtrar variáveis"/><div class="max-h-96 overflow-auto border rounded-2xl p-3 space-y-2"><label v-for="v in filteredVariables" :key="v.codVariavel" class="flex gap-2 text-sm"><input v-model="selected" type="checkbox" :value="v.codVariavel"/><span>{{v.nome}} <small class="text-gray-500">{{v.variavel}}</small></span></label></div></div><template #footer><DsButton variant="secondary" @click="association=false">Cancelar</DsButton><DsButton v-if="auth.isAdmin" @click="associate">Aplicar</DsButton></template></DsModal></div></template>
<script setup lang="ts">definePageMeta({layout:'default'});const api=useApi(),auth=useAuthStore(),swal=useSwal();const grupos=ref<any[]>([]),variables=ref<any[]>([]),error=ref(''),modal=ref(false),association=ref(false),editing=ref<any>(null),selected=ref<number[]>([]),targetGroup=ref(''),search=ref(''),form=reactive({nome:'',descricao:'',ativo:'1'});const filteredVariables=computed(()=>variables.value.filter(v=>`${v.nome} ${v.variavel}`.toLowerCase().includes(search.value.toLowerCase())));async function load(){try{const[g,v]=await Promise.all([api.get<any>('/api/web/cadastros/grupos-variaveis'),api.get<any>('/api/web/cadastros/grupos-variaveis/variaveis')]);grupos.value=g.data||[];variables.value=v.data||[]}catch(e){error.value=e instanceof Error?e.message:'Erro ao carregar.'}}function open(g?:any){editing.value=g||null;form.nome=g?.nome||'';form.descricao=g?.descricao||'';form.ativo=String(g?.ativo??1);modal.value=true}async function save(){try{const body={nome:form.nome,descricao:form.descricao||null,ativo:Number(form.ativo)};editing.value?await api.put(`/api/web/cadastros/grupos-variaveis/${editing.value.codGrupo}`,body):await api.post('/api/web/cadastros/grupos-variaveis',body);modal.value=false;await load()}catch(e){await swal.toast(e instanceof Error?e.message:'Erro ao salvar.','error')}}async function remove(g:any){const c=await swal.confirm('Excluir grupo',`Excluir "${g.nome}"?`);if(!c?.isConfirmed)return;try{await api.del(`/api/web/cadastros/grupos-variaveis/${g.codGrupo}`);await load()}catch(e){await swal.toast(e instanceof Error?e.message:'Erro ao excluir.','error')}}async function associate(){try{await api.put('/api/web/cadastros/grupos-variaveis/associacoes',{codigosVariaveis:selected.value,codGrupo:targetGroup.value?Number(targetGroup.value):null});association.value=false;selected.value=[];await load();await swal.toast('Associações atualizadas.')}catch(e){await swal.toast(e instanceof Error?e.message:'Erro ao associar.','error')}}onMounted(load)</script>
